<?php
require_once __DIR__.'/../includes/functions.php';require_login();$uid=(int)current_user()['user_id'];$errors=[];
if($_SERVER['REQUEST_METHOD']==='POST') {
    $title=input('title');$category=(int)input('category_id');$description=input('description');$url=input('content_url');
    if(!$title || mb_strlen($title)>255) $errors[]='Enter a title up to 255 characters.';
    if(!db_one('SELECT category_id FROM categories WHERE category_id=? AND is_active=1',[$category])) $errors[]='Choose a category.';
    if(mb_strlen($description)<20 || mb_strlen($description)>20000) $errors[]='Write between 20 and 20,000 characters.';
    if($url && !safe_url($url)) $errors[]='Use a valid HTTP or HTTPS resource link.';
    if(!$errors) try {
        $image=upload_image('image','submissions');
        db_query('INSERT INTO fan_submissions(user_id,category_id,title,description,content_url,image_url) VALUES(?,?,?,?,?,?)',[$uid,$category,$title,$description,$url,$image]);
        log_activity($uid,'fan_submitted','fan_submission',(int)$conn->insert_id);flash('success','Submitted for review. It will only become public after approval.');redirect(base_url('User/submit-content.php'));
    } catch(InvalidArgumentException|RuntimeException $error){$errors[]=$error->getMessage();}
}
$rows=db_all('SELECT * FROM fan_submissions WHERE user_id=? ORDER BY submission_id DESC',[$uid]);$page_title='Submit fan work';require __DIR__.'/../includes/user_header.php';
?>
<main id="main" class="page"><h1>Share your fan work</h1><p>Submit an original article, guide or creative work. Every submission is reviewed before publication.</p><div class="two-column"><form method="post" enctype="multipart/form-data" class="panel"><?=csrf_field()?><?php if($errors):?><div class="errors"><?=e(implode(' ',$errors))?></div><?php endif;?><div class="field"><label for="title">Title</label><input id="title" name="title" required maxlength="255" value="<?=e(input('title'))?>"></div><div class="field"><label for="category">Fandom category</label><select id="category" name="category_id" required><option value="">Choose category</option><?php foreach(categories() as $cat):?><option value="<?=$cat['category_id']?>" <?=(int)input('category_id')===(int)$cat['category_id']?'selected':''?>><?=e($cat['name'])?></option><?php endforeach;?></select></div><div class="field"><label for="description">Your work / article</label><textarea id="description" name="description" required minlength="20" maxlength="20000" rows="10"><?=e(input('description'))?></textarea></div><div class="field"><label for="content_url">Supporting resource URL (optional)</label><input id="content_url" name="content_url" type="url" maxlength="700" value="<?=e(input('content_url'))?>"></div><div class="field"><label for="image">Image (optional)</label><input id="image" name="image" type="file" accept="image/jpeg,image/png,image/webp"><small>Upload images you have permission to share. Up to 5 MB.</small></div><button class="button">Submit for review</button></form><aside><h2>Your submissions</h2><?php foreach($rows as $row):?><article class="panel"><span class="pill"><?=e($row['status'])?></span><h3 style="margin-top:12px"><?=e($row['title'])?></h3><p><?=e($row['admin_notes']??'Awaiting administrator review.')?></p><?php if($row['status']==='approved' && $row['article_id']):?><a href="<?=e(base_url('article.php?id='.$row['article_id']))?>">View published article</a><?php endif;?></article><?php endforeach;if(!$rows):?><p>Your submissions and review status will appear here.</p><?php endif;?></aside></div></main><?php require __DIR__.'/../includes/footer.php';?>
